#include <iostream>
#include <iomanip>
using namespace std;

// 函数模板：T 是「占位类型」，调用时由编译器根据实参自动推断。
// 写一次，int 版本和 double 版本都由编译器替你生成。
template <typename T>
T maxOf(T a, T b) {
    return a > b ? a : b;
}

int main() {
    int a, b;
    double x, y;
    cin >> a >> b;
    cin >> x >> y;

    // 同一个 maxOf 用了两次，实参类型不同 → 编译器生成两个不同的函数
    cout << maxOf(a, b) << endl;

    // fixed + setprecision(2) 一旦设置就持续生效，
    // 所以放在整数输出之后，否则整数也会被写成 "8.00"
    cout << fixed << setprecision(2) << maxOf(x, y) << endl;
    return 0;
}

