#include <iostream>
#include <vector>
using namespace std;

int main() {
    int n;
    cin >> n;

    vector<int> v;              // 一开始是空的，容量随 push_back 自动增长
    for (int i = 0; i < n; i++) {
        int x;
        cin >> x;
        v.push_back(x);         // 追加到末尾，等价于 C 里的 a[len++] = x
    }

    // 关键：mx 用第一个元素初始化。
    // 如果写 int mx = 0，当所有数都是负数时答案会错成 0。
    int sum = 0;
    int mx = v[0];
    for (int x : v) {           // 范围 for：依次取出每个元素，不用管下标
        sum += x;
        if (x > mx) mx = x;
    }

    cout << sum << endl;
    cout << mx << endl;
    return 0;
}

