#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

int main() {
    int n;
    cin >> n;

    vector<int> v;
    for (int i = 0; i < n; i++) {
        int x;
        cin >> x;
        v.push_back(x);
    }

    // begin() 指向第一个元素，end() 指向「最后一个元素的下一个位置」。
    // sort 排的是 [begin, end) 这个左闭右开区间。
    sort(v.begin(), v.end());

    // 空格分隔的稳妥写法：第一个数单独输出，后面的数前面补一个空格，
    // 这样行尾不会多出一个空格。
    cout << v[0];
    for (size_t i = 1; i < v.size(); i++) {
        cout << " " << v[i];
    }
    cout << endl;
    return 0;
}

