#include <iostream>
#include <string>
#include <algorithm>
using namespace std;

int main() {
    string s;
    cin >> s;                   // cin >> 遇到空白就停，读不含空格的字符串正合适

    string t = s;               // 备份一份：sort 和 reverse 都是就地修改原串

    sort(s.begin(), s.end());   // 字符按 ASCII 升序，小写字母即字典序
    cout << s << endl;

    reverse(t.begin(), t.end());
    cout << t << endl;
    return 0;
}

