#include <iostream>
#include <map>
using namespace std;

int main() {
    int n;
    cin >> n;

    map<int, int> cnt;          // 键是数字，值是出现次数
    for (int i = 0; i < n; i++) {
        int x;
        cin >> x;
        // operator[] 的副作用：键不存在时先插入一个 0，再自增。
        // 所以这一行同时完成「没见过的数字就新建」和「计数加一」。
        cnt[x]++;
    }

    // map 内部按 key 排好序，遍历顺序就是数字从小到大，不用再 sort。
    // auto& 里的 & 很重要：不加就每轮拷贝一份键值对。
    for (auto& p : cnt) {
        cout << p.first << " " << p.second << endl;
    }
    return 0;
}

