#include <iostream>
#include <string>
#include <vector>
#include <algorithm>
using namespace std;

// 自定义比较函数：返回 true 表示 a 应该排在 b 前面。
// 参数用 const 引用，避免每比较一次就拷贝一份字符串。
bool cmp(const pair<string, int>& a, const pair<string, int>& b) {
    if (a.second != b.second) {
        return a.second > b.second;     // 分数高的排前面
    }
    return a.first < b.first;           // 分数相同，姓名小的排前面
}

int main() {
    int n;
    cin >> n;

    // 一个人 = 一个 pair，整条记录一起搬，排序时姓名不会和分数走散
    vector<pair<string, int> > v;
    for (int i = 0; i < n; i++) {
        string name;
        int score;
        cin >> name >> score;
        v.push_back(make_pair(name, score));
    }

    sort(v.begin(), v.end(), cmp);      // 把比较规则交给 cmp

    for (auto& p : v) {
        cout << p.first << " " << p.second << endl;
    }
    return 0;
}

