// 错误示范：相等时也返回 true
bool bad(const pair<string,int>& a, const pair<string,int>& b) {
    return a.second <= b.second;      // sort 可能崩溃
}

// 正确：相等的情况由后面的条件兜住，返回 false
bool cmp(const pair<string,int>& a, const pair<string,int>& b) {
    if (a.second != b.second) return a.second > b.second;
    return a.first < b.first;
}
